DECLARE @school_year smallint=?,@grade_code varchar(2)=?,@class_code varchar(9)=?,@class_name nvarchar(36)=?,@valid_from date=?,@valid_to date=?,@capacity int=?,@display_order int=?,@is_active bit=?,@remarks nvarchar(240)=?,@actor nvarchar(128)=?,@now datetimeoffset(7)=?; DECLARE @saved TABLE(id bigint); DECLARE @id bigint=?,@version bigint=?; UPDATE dbo.m_class SET school_year=@school_year,grade_code=@grade_code,class_code=@class_code,class_name=@class_name,valid_from=@valid_from,valid_to=@valid_to,capacity=@capacity,display_order=@display_order,is_active=@is_active,remarks=@remarks,updated_at=@now,updated_by=@actor,row_version=row_version+1 OUTPUT INSERTED.class_id INTO @saved WHERE class_id=@id AND row_version=@version; SELECT id FROM @saved;
